import json
session_id = 'f12aa083-ea49-458b-87fa-baaa6ecff603'
with open('/home/prabhanshu/.claude/history.jsonl', 'r') as f:
    user_messages = []
    for line in f:
        try:
            data = json.loads(line.strip())
            if data.get('sessionId') == session_id and 'display' in data:
                user_messages.append(data['display'])
        except:
            continue

for i, msg in enumerate(user_messages):
    print(f'{i+1}. {msg}')
    print()
